const char *gsw(const struct gswtab *t, int line, int value, int k)
{
    int i;
    for (i = 0; i < t->n; i++)
        if (t->c[i].line == line && t->c[i].value == value && k < t->c[i].n)
            return t->c[i].lits[k];
    return 0;
}
